import type {
	OpenUIDocumentMetadata,
	OpenUIInteractionLifecycle,
	OpenUIMessageSegment,
} from "./types";

const OPENUI_FENCE = /```openui(?:-lang)?(?:[ \t]+([^\n]*))?\n/g;
const CLOSE_FENCE = /\n```(?:\n|$)/g;
const DOCUMENT_ID = /^[a-zA-Z0-9][a-zA-Z0-9._:-]{0,127}$/;

function hashProgram(program: string): string {
	let hash = 2166136261;
	for (let index = 0; index < program.length; index += 1) {
		hash ^= program.charCodeAt(index);
		hash = Math.imul(hash, 16777619);
	}
	return (hash >>> 0).toString(36);
}

function parseLifecycle(value: string | undefined): OpenUIInteractionLifecycle {
	if (value === "resumable" || value === "workspace") return value;
	return "ephemeral";
}

function parseMetadata(header: string | undefined, _program: string, sourceIndex = 0): OpenUIDocumentMetadata {
	const entries = new Map<string, string>();
	for (const token of header?.trim().split(/\s+/) ?? []) {
		const separator = token.indexOf("=");
		if (separator <= 0) continue;
		entries.set(token.slice(0, separator), token.slice(separator + 1));
	}
	const candidateId = entries.get("id");
	return {
		id: candidateId && DOCUMENT_ID.test(candidateId)
			? candidateId
			: `openui-${hashProgram(`${header ?? ""}:${sourceIndex}`)}`,
		lifecycle: parseLifecycle(entries.get("lifecycle")),
	};
}

/**
 * Split assistant text into Markdown and OpenUI programs.
 *
 * An opening fence is enough to produce an OpenUI segment, so the renderer can
 * consume the program while the assistant is still streaming it. Existing
 * Markdown and legacy `<keating-*>` tags remain untouched in text segments.
 */
export function parseOpenUIMessageSegments(text: string): OpenUIMessageSegment[] {
	const segments: OpenUIMessageSegment[] = [];
	let cursor = 0;
	OPENUI_FENCE.lastIndex = 0;
	let match: RegExpExecArray | null;

	while ((match = OPENUI_FENCE.exec(text)) !== null) {
		if (match.index > cursor) {
			segments.push({ type: "text", content: text.slice(cursor, match.index) });
		}

		const bodyStart = OPENUI_FENCE.lastIndex;
		CLOSE_FENCE.lastIndex = bodyStart;
		const closing = CLOSE_FENCE.exec(text);
		const bodyEnd = closing?.index ?? text.length;
		const program = text.slice(bodyStart, bodyEnd);
		segments.push({
			type: "openui",
			program,
			complete: closing !== null,
			metadata: parseMetadata(match[1], program, match.index),
		});

		if (!closing) {
			cursor = text.length;
			break;
		}
		cursor = CLOSE_FENCE.lastIndex;
		OPENUI_FENCE.lastIndex = cursor;
	}

	if (cursor < text.length) segments.push({ type: "text", content: text.slice(cursor) });
	if (segments.length === 0) segments.push({ type: "text", content: text });
	return segments;
}

/** Remove OpenUI source from text copied from an assistant message. */
export function stripOpenUIPrograms(text: string): string {
	return parseOpenUIMessageSegments(text)
		.filter((segment): segment is Extract<OpenUIMessageSegment, { type: "text" }> => segment.type === "text")
		.map((segment) => segment.content)
		.join("")
		.trim();
}

export const __test_parseOpenUIMetadata = parseMetadata;

import { describe, expect, it } from "bun:test";

import {
	parseOpenUIMessageSegments,
	stripOpenUIPrograms,
} from "../keating/openui/segments";

describe("OpenUI message segments", () => {
	it("preserves Markdown around a complete OpenUI document", () => {
		const text = [
			"Before",
			"```openui lifecycle=resumable id=fractions-check",
			'root = Explanation({ markdown: "A whole can be partitioned." })',
			"```",
			"After",
		].join("\n");
		const segments = parseOpenUIMessageSegments(text);

		expect(segments.map((segment) => segment.type)).toEqual(["text", "openui", "text"]);
		const document = segments[1];
		if (document.type !== "openui") throw new Error("expected OpenUI segment");
		expect(document.complete).toBe(true);
		expect(document.metadata).toEqual({ id: "fractions-check", lifecycle: "resumable" });
		expect(document.program).toContain("partitioned");
	});

	it("returns an incomplete document while a response is streaming", () => {
		const segments = parseOpenUIMessageSegments(
			"```openui lifecycle=workspace id=map-1\nroot = ConceptMap({ code: \"graph TD",
		);
		const document = segments[0];
		if (document.type !== "openui") throw new Error("expected OpenUI segment");
		expect(document.complete).toBe(false);
		expect(document.metadata.lifecycle).toBe("workspace");
	});

	it("keeps an inferred document id stable as a program streams", () => {
		const prefix = "Lesson\n```openui lifecycle=ephemeral\nroot = Callout({";
		const first = parseOpenUIMessageSegments(prefix)[1];
		const second = parseOpenUIMessageSegments(`${prefix} tone: \"hint\"`)[1];
		if (first.type !== "openui" || second.type !== "openui") {
			throw new Error("expected OpenUI segments");
		}
		expect(first.metadata.id).toBe(second.metadata.id);
	});

	it("defaults malformed metadata safely", () => {
		const [document] = parseOpenUIMessageSegments("```openui lifecycle=forever id=bad/id\nroot = Nope({})\n```");
		if (document.type !== "openui") throw new Error("expected OpenUI segment");
		expect(document.metadata.lifecycle).toBe("ephemeral");
		expect(document.metadata.id).toMatch(/^openui-/);
	});

	it("removes programs without discarding surrounding prose", () => {
		const text = "One\n```openui id=x\nroot = Explanation({ markdown: \"hidden\" })\n```\nTwo";
		expect(stripOpenUIPrograms(text)).toBe("One\nTwo");
	});

	it("leaves legacy messages unchanged", () => {
		const legacy = '<keating-question json={"question":"Why?"} />';
		expect(parseOpenUIMessageSegments(legacy)).toEqual([{ type: "text", content: legacy }]);
	});
});

