// `foreignObject` is intentionally allowed: Mermaid uses it to render
// HTML-styled node labels (the labels we want the learner to actually read).
// Mermaid is the only source of the SVG we sanitize, and it does not place
// any script-capable content inside foreignObject. The other elements here
// (`script`, `iframe`, `object`, `embed`, `link`, `meta`, `base`) are still
// stripped unconditionally because they can carry executable content.
const FORBIDDEN_ELEMENTS = new Set(["script", "iframe", "object", "embed", "link", "meta", "base"]);
const URL_ATTRIBUTES = new Set(["href", "xlink:href", "src"]);

function hasUnsafeCss(value: string): boolean {
	const lower = value.toLowerCase();
	return lower.includes("javascript:") || lower.includes("@import") || lower.includes("expression(");
}

function isSafeUrlAttribute(value: string): boolean {
	const trimmed = value.trim().toLowerCase();
	return (
		trimmed === "" ||
		trimmed.startsWith("#") ||
		trimmed.startsWith("data:image/png") ||
		trimmed.startsWith("data:image/jpeg") ||
		trimmed.startsWith("data:image/gif") ||
		trimmed.startsWith("data:image/webp")
	);
}

// Mermaid emits SVG markup that is not always well-formed XML — most commonly
// HTML entities (e.g. `&nbsp;`) that are undefined in XML, which makes the
// strict `image/svg+xml` parser bail with a <parsererror>. Parsing that output
// as HTML instead is lenient about entities and, per the HTML spec's SVG
// attribute-adjustment table, preserves camelCase SVG attributes like
// `viewBox`/`preserveAspectRatio`. We try strict XML first (to keep behavior
// identical for well-formed input) and only fall back to the HTML parser when
// XML parsing fails, so a valid diagram is never silently dropped.
function parseSvgRoot(svg: string): SVGElement | null {
	const xmlDoc = new DOMParser().parseFromString(svg, "image/svg+xml");
	if (!xmlDoc.querySelector("parsererror")) {
		const xmlRoot = xmlDoc.documentElement;
		if (xmlRoot && xmlRoot.tagName.toLowerCase() === "svg") {
			return xmlRoot as unknown as SVGElement;
		}
	}

	// Lenient fallback: parse as HTML and pull the first <svg> element.
	const htmlDoc = new DOMParser().parseFromString(svg, "text/html");
	const htmlRoot = htmlDoc.querySelector("svg");
	return htmlRoot ?? null;
}

export function sanitizeSvg(svg: string): string {
	if (typeof DOMParser === "undefined" || typeof XMLSerializer === "undefined") {
		return "";
	}

	const root = parseSvgRoot(svg);
	if (!root) return "";
	const doc = root.ownerDocument;
	const showElement = typeof NodeFilter === "undefined" ? 1 : NodeFilter.SHOW_ELEMENT;

	const removals: Element[] = [];
	const walker = doc.createTreeWalker(root, showElement);
	let current: Node | null = walker.currentNode;

	while (current) {
		const element = current as Element;
		const tagName = element.tagName.toLowerCase();
		if (FORBIDDEN_ELEMENTS.has(tagName)) {
			removals.push(element);
		} else {
			for (const attribute of Array.from(element.attributes)) {
				const name = attribute.name.toLowerCase();
				const value = attribute.value;
				if (name.startsWith("on")) {
					element.removeAttribute(attribute.name);
					continue;
				}
				if (name === "style" && hasUnsafeCss(value)) {
					element.removeAttribute(attribute.name);
					continue;
				}
				if (URL_ATTRIBUTES.has(name) && !isSafeUrlAttribute(value)) {
					element.removeAttribute(attribute.name);
				}
			}
			if (tagName === "style" && hasUnsafeCss(element.textContent ?? "")) {
				removals.push(element);
			}
		}
		current = walker.nextNode();
	}

	for (const element of removals) {
		element.remove();
	}

	return new XMLSerializer().serializeToString(root);
}

export type KeatingAgentRuntimeMode = "browser-only" | "browser-nodepod" | "remote" | "cloud";

// Overlay NodePod browser sandbox when locally active
import { isNodePodActive, NODEPOD_LOCAL_ENDPOINT } from "./nodepod-runtime";

export interface KeatingRemoteAgentRuntimeConfig {
  provider: string;
  endpoint: string | null;
  region: string | null;
  snapshot: string | null;
  cpu: string | null;
  memory: string | null;
  disk: string | null;
}

export interface KeatingAgentRuntimeCapabilities {
  browserLocal: boolean;
  remoteSandbox: boolean;
  secureIsolation: boolean;
  nativeBinaries: boolean;
  serverBrokeredSecrets: boolean;
  durableCompute: boolean;
  hostProjectAccess: boolean;
  /** Opt-in localhost host command execution + file writes (keating web --allow-local-exec). */
  localCommandExecution: boolean;
}

export interface KeatingAgentRuntimeConfig {
  mode: KeatingAgentRuntimeMode;
  label: string;
  executionEndpoint: string | null;
  cloudEndpoint: string | null;
  projectRoot: string | null;
  projectFilesEndpoint: string | null;
  /** Base endpoint for local exec/write routes, or null when disabled. */
  localExecEndpoint: string | null;
  remote: KeatingRemoteAgentRuntimeConfig | null;
  capabilities: KeatingAgentRuntimeCapabilities;
  fallback: {
    localFirst: boolean;
    remoteAvailable: boolean;
    message: string;
  };
}

const DEFAULT_CLOUD_ENDPOINT = "https://keating.help";

export const DEFAULT_AGENT_RUNTIME_CONFIG: KeatingAgentRuntimeConfig = {
  mode: "browser-only",
  label: "Browser-only agent",
  executionEndpoint: null,
  cloudEndpoint: null,
  projectRoot: null,
  projectFilesEndpoint: null,
  localExecEndpoint: null,
  remote: null,
  capabilities: {
    browserLocal: true,
    remoteSandbox: false,
    secureIsolation: false,
    nativeBinaries: false,
    serverBrokeredSecrets: false,
    durableCompute: false,
    hostProjectAccess: false,
    localCommandExecution: false,
  },
  fallback: {
    localFirst: true,
    remoteAvailable: false,
    message: "Run supported agent work in the browser. Surface a fallback error for secure isolation, native binaries, brokered secrets, durable compute, or public inbound networking.",
  },
};

let runtimeConfigPromise: Promise<KeatingAgentRuntimeConfig> | null = null;

export function shouldAutoBootNodePod(config: KeatingAgentRuntimeConfig): boolean {
  return config.mode === "browser-only";
}

export function shouldRouteExecutionToNodePod(config: KeatingAgentRuntimeConfig | null | undefined): boolean {
  return config?.mode === "browser-nodepod";
}

export function applyNodePodRuntimeOverlay(
  config: KeatingAgentRuntimeConfig,
  nodePodActive: boolean,
): KeatingAgentRuntimeConfig {
  // Explicit remote and cloud serving modes are authoritative. A stale or
  // manually booted local pod must never capture work intended for an external
  // sandbox.
  if (!nodePodActive || config.mode !== "browser-only") return config;

  return {
    ...config,
    mode: "browser-nodepod",
    label: "Browser + NodePod agent",
    executionEndpoint: NODEPOD_LOCAL_ENDPOINT,
    capabilities: {
      ...config.capabilities,
      remoteSandbox: true,
      secureIsolation: false,
      nativeBinaries: false,
    },
    fallback: {
      localFirst: true,
      remoteAvailable: true,
      message: "NodePod browser sandbox is active. Run filesystem, shell, and snapshot work locally. Secure isolation, native binaries, and server-brokered secrets still require a remote backend.",
    },
  };
}

export function normalizeAgentRuntimeConfig(value: unknown): KeatingAgentRuntimeConfig {
  if (!value || typeof value !== "object") return DEFAULT_AGENT_RUNTIME_CONFIG;
  const raw = value as Partial<KeatingAgentRuntimeConfig>;
  const mode = raw.mode === "remote" || raw.mode === "cloud" || raw.mode === "browser-only"
    ? raw.mode
    : "browser-only";

  if (mode === "browser-only") {
    const projectFilesEndpoint = raw.projectFilesEndpoint ?? null;
    const localExecEndpoint = raw.localExecEndpoint ?? null;
    return {
      ...DEFAULT_AGENT_RUNTIME_CONFIG,
      projectRoot: raw.projectRoot ?? null,
      projectFilesEndpoint,
      localExecEndpoint,
      capabilities: {
        ...DEFAULT_AGENT_RUNTIME_CONFIG.capabilities,
        hostProjectAccess: !!projectFilesEndpoint,
        localCommandExecution: !!localExecEndpoint,
      },
    };
  }

  const remote = raw.remote && typeof raw.remote === "object"
    ? {
        provider: String(raw.remote.provider || "microsandbox"),
        endpoint: raw.remote.endpoint || null,
        region: raw.remote.region || null,
        snapshot: raw.remote.snapshot || null,
        cpu: raw.remote.cpu || null,
        memory: raw.remote.memory || null,
        disk: raw.remote.disk || null,
      }
    : null;

  if (mode === "remote") {
	const executionEndpoint = raw.executionEndpoint ?? (remote?.endpoint ? "/api/agent-runtime/remote" : null);
	const remoteAvailable = !!executionEndpoint && !!remote?.endpoint;
	const hostProvider = remote?.provider === "host";
    return {
      mode,
	  label: remoteAvailable
		? (hostProvider ? "Host execution agent" : "Remote microVM agent")
		: (hostProvider ? "Host execution unavailable" : "Remote microVM unavailable"),
	  executionEndpoint,
      cloudEndpoint: null,
      projectRoot: raw.projectRoot ?? null,
      projectFilesEndpoint: raw.projectFilesEndpoint ?? null,
      localExecEndpoint: raw.localExecEndpoint ?? null,
      remote: remote ?? {
        provider: "microsandbox",
        endpoint: null,
        region: null,
        snapshot: null,
        cpu: null,
        memory: null,
        disk: null,
      },
      capabilities: {
        browserLocal: true,
		remoteSandbox: remoteAvailable,
		secureIsolation: remoteAvailable && !hostProvider,
		nativeBinaries: remoteAvailable,
		serverBrokeredSecrets: remoteAvailable && !hostProvider,
		durableCompute: remoteAvailable && !hostProvider,
        hostProjectAccess: !!raw.projectFilesEndpoint,
        localCommandExecution: !!raw.localExecEndpoint,
      },
      fallback: {
        localFirst: true,
		remoteAvailable,
		message: remoteAvailable
			? (hostProvider
				? "Host execution is enabled. Commands run directly on the serving machine inside the configured project root; this is not a security sandbox."
				: "Run browser-compatible work locally first. Route secure isolation, native binaries, brokered secrets, durable compute, and public networking to the configured remote sandbox.")
			: "Remote mode was requested, but no external sandbox endpoint is configured.",
      },
    };
  }

  return {
    mode,
    label: "Keating Cloud agent",
    executionEndpoint: "/api/agent-runtime/remote",
    cloudEndpoint: raw.cloudEndpoint || DEFAULT_CLOUD_ENDPOINT,
    projectRoot: raw.projectRoot ?? null,
    projectFilesEndpoint: raw.projectFilesEndpoint ?? null,
    localExecEndpoint: raw.localExecEndpoint ?? null,
    remote: null,
    capabilities: {
      browserLocal: true,
      remoteSandbox: true,
      secureIsolation: true,
      nativeBinaries: true,
      serverBrokeredSecrets: true,
      durableCompute: true,
      hostProjectAccess: !!raw.projectFilesEndpoint,
      localCommandExecution: !!raw.localExecEndpoint,
    },
    fallback: {
      localFirst: true,
      remoteAvailable: true,
      message: "Run browser-compatible work locally first. Route remote-only work through the canonical Keating Cloud backend.",
    },
  };
}

export async function loadAgentRuntimeConfig(force = false): Promise<KeatingAgentRuntimeConfig> {
  if (runtimeConfigPromise && !force) return runtimeConfigPromise;
  runtimeConfigPromise = fetch("/api/agent-runtime/config", { headers: { accept: "application/json" } })
    .then((response) => response.ok ? response.json() : DEFAULT_AGENT_RUNTIME_CONFIG)
    .then(normalizeAgentRuntimeConfig)
    .then((config) => applyNodePodRuntimeOverlay(config, isNodePodActive()))
    .catch(() => DEFAULT_AGENT_RUNTIME_CONFIG);
  return runtimeConfigPromise;
}

import { defineEventHandler } from "h3";

type Mode = "browser-only" | "remote" | "cloud";

function env(name: string): string | null {
  const value = process.env[name]?.trim();
  return value ? value : null;
}

function modeFromEnv(): Mode {
  const mode = env("KEATING_WEB_AGENT_MODE");
  return mode === "remote" || mode === "cloud" || mode === "browser-only" ? mode : "browser-only";
}

export default defineEventHandler(() => {
  const mode = modeFromEnv();

  const projectRootRaw = env("KEATING_WEB_PROJECT_ROOT");
  const projectRoot = projectRootRaw ?? null;

  // Local exec is opt-in, requires a project root, and is a localhost-only
  // trust surface. The endpoint is only advertised when both are satisfied.
  const localExecEnabled =
    !!projectRoot &&
    (process.env.KEATING_WEB_LOCAL_EXEC === "1" || process.env.KEATING_WEB_LOCAL_EXEC === "true");
  const localExecEndpoint = localExecEnabled ? "/api/local-exec" : null;

  if (mode === "browser-only") {
    return {
      mode,
      label: "Browser-only agent",
      executionEndpoint: null,
      cloudEndpoint: null,
      projectRoot,
      projectFilesEndpoint: projectRoot ? "/api/project-files" : null,
      localExecEndpoint,
      remote: null,
      capabilities: {
        browserLocal: true,
        remoteSandbox: false,
        secureIsolation: false,
        nativeBinaries: false,
        serverBrokeredSecrets: false,
        durableCompute: false,
        hostProjectAccess: !!projectRoot,
        localCommandExecution: localExecEnabled,
      },
      fallback: {
        localFirst: true,
        remoteAvailable: false,
        message: "Run supported agent work in the browser. Surface a fallback error for secure isolation, native binaries, brokered secrets, durable compute, or public inbound networking.",
      },
    };
  }

  if (mode === "remote") {
	const remoteProvider = env("KEATING_WEB_REMOTE_PROVIDER") ?? "microsandbox";
	const hostProvider = remoteProvider === "host";
	const remoteEndpoint = hostProvider ? "host://local" : env("KEATING_WEB_REMOTE_ENDPOINT");
	const remoteAvailable = hostProvider ? localExecEnabled : !!remoteEndpoint;
    return {
      mode,
	  label: remoteAvailable
		? (hostProvider ? "Host execution agent" : "Remote microVM agent")
		: (hostProvider ? "Host execution unavailable" : "Remote microVM unavailable"),
	  executionEndpoint: remoteAvailable
		? (hostProvider ? "/api/agent-runtime/host" : "/api/agent-runtime/remote")
		: null,
      cloudEndpoint: null,
      projectRoot,
      projectFilesEndpoint: projectRoot ? "/api/project-files" : null,
      localExecEndpoint,
      remote: {
		provider: remoteProvider,
		endpoint: remoteEndpoint,
        region: env("KEATING_WEB_REMOTE_REGION"),
        snapshot: env("KEATING_WEB_REMOTE_SNAPSHOT"),
        cpu: env("KEATING_WEB_REMOTE_CPU"),
        memory: env("KEATING_WEB_REMOTE_MEMORY"),
        disk: env("KEATING_WEB_REMOTE_DISK"),
      },
      capabilities: {
        browserLocal: true,
		remoteSandbox: remoteAvailable,
		secureIsolation: remoteAvailable && !hostProvider,
		nativeBinaries: remoteAvailable,
		serverBrokeredSecrets: remoteAvailable && !hostProvider,
		durableCompute: remoteAvailable && !hostProvider,
        hostProjectAccess: !!projectRoot,
        localCommandExecution: localExecEnabled,
      },
      fallback: {
        localFirst: true,
		remoteAvailable,
		message: remoteAvailable
			? (hostProvider
				? "Host execution is enabled. Commands run directly on the serving machine inside the configured project root; this is not a security sandbox."
				: "Run browser-compatible work locally first. Route secure isolation, native binaries, brokered secrets, durable compute, and public networking to the configured remote sandbox.")
			: (hostProvider
				? "Host execution requires --allow-local-exec and a configured project root."
				: "Remote mode was requested, but KEATING_WEB_REMOTE_ENDPOINT is not configured."),
      },
    };
  }

  return {
    mode,
    label: "Keating Cloud agent",
    executionEndpoint: "/api/agent-runtime/remote",
    cloudEndpoint: env("KEATING_WEB_CLOUD_ENDPOINT") ?? "https://keating.help",
    projectRoot,
    projectFilesEndpoint: projectRoot ? "/api/project-files" : null,
    localExecEndpoint,
    remote: null,
    capabilities: {
      browserLocal: true,
      remoteSandbox: true,
      secureIsolation: true,
      nativeBinaries: true,
      serverBrokeredSecrets: true,
      durableCompute: true,
      hostProjectAccess: !!projectRoot,
      localCommandExecution: localExecEnabled,
    },
    fallback: {
      localFirst: true,
      remoteAvailable: true,
      message: "Run browser-compatible work locally first. Route remote-only work through the canonical Keating Cloud backend.",
    },
  };
});

