import type { AgentMessage } from "@earendil-works/pi-agent-core";

export const INTERRUPTED_RESPONSE_MESSAGE =
	"The response was interrupted before it finished. Retry to generate it again.";

type AssistantLike = AgentMessage & {
	role?: unknown;
	content?: unknown;
	stopReason?: unknown;
	errorMessage?: unknown;
};

function cloneMessage(message: AgentMessage): AgentMessage {
	const content = (message as AssistantLike).content;
	return {
		...message,
		...(Array.isArray(content)
			? { content: content.map((part) => (part && typeof part === "object" ? { ...part } : part)) }
			: {}),
	} as AgentMessage;
}

export function isRetryableAssistantMessage(message: AgentMessage | undefined): boolean {
	if (!message) return false;
	const entry = message as AssistantLike;
	return entry.role === "assistant" && (entry.stopReason === "error" || entry.stopReason === "aborted");
}

export function messagesForSessionSnapshot(
	messages: AgentMessage[],
	streamingMessage: AgentMessage | undefined,
): { messages: AgentMessage[]; interrupted: boolean } {
	const stableMessages = messages.map(cloneMessage);
	if (!streamingMessage || (streamingMessage as AssistantLike).role !== "assistant") {
		return { messages: stableMessages, interrupted: false };
	}

	const interrupted = cloneMessage(streamingMessage) as AssistantLike;
	interrupted.stopReason = "aborted";
	interrupted.errorMessage = INTERRUPTED_RESPONSE_MESSAGE;
	return {
		messages: [...stableMessages, interrupted as AgentMessage],
		interrupted: true,
	};
}

export function prepareMessagesForRetry(messages: AgentMessage[]): AgentMessage[] | null {
	if (!isRetryableAssistantMessage(messages.at(-1))) return null;
	const remaining = messages.slice(0, -1).map(cloneMessage);
	const last = remaining.at(-1) as { role?: unknown } | undefined;
	return last?.role === "user" || last?.role === "user-with-attachments" || last?.role === "toolResult"
		? remaining
		: null;
}

import { describe, expect, it } from "bun:test";
import type { AgentMessage } from "@earendil-works/pi-agent-core";
import {
	INTERRUPTED_RESPONSE_MESSAGE,
	isRetryableAssistantMessage,
	messagesForSessionSnapshot,
	prepareMessagesForRetry,
} from "../hooks/session-recovery";

const user = (text = "hello") => ({
	role: "user",
	content: [{ type: "text", text }],
	timestamp: 1,
}) as AgentMessage;

const assistant = (stopReason: "stop" | "error" | "aborted" | undefined, text = "reply") => ({
	role: "assistant",
	content: [{ type: "text", text }],
	stopReason,
	timestamp: 2,
}) as AgentMessage;

describe("session interruption recovery", () => {
	it("stores a live assistant response as an interrupted, retryable message", () => {
		const snapshot = messagesForSessionSnapshot([user()], assistant(undefined, "partial reply"));
		expect(snapshot.interrupted).toBe(true);
		expect(snapshot.messages).toHaveLength(2);
		expect((snapshot.messages[1] as any).stopReason).toBe("aborted");
		expect((snapshot.messages[1] as any).errorMessage).toBe(INTERRUPTED_RESPONSE_MESSAGE);
		expect(isRetryableAssistantMessage(snapshot.messages[1])).toBe(true);
	});

	it("does not append a non-assistant streaming message", () => {
		const snapshot = messagesForSessionSnapshot([], user());
		expect(snapshot).toEqual({ messages: [], interrupted: false });
	});

	it("removes only the trailing failed response before retrying", () => {
		const prompt = user();
		const retryMessages = prepareMessagesForRetry([prompt, assistant("error")]);
		expect(retryMessages).toEqual([prompt]);
		expect(retryMessages).not.toBe([prompt]);
	});

	it("does not retry a completed or non-trailing failure", () => {
		expect(prepareMessagesForRetry([user(), assistant("stop")])).toBeNull();
		expect(prepareMessagesForRetry([user(), assistant("error"), user("later")])).toBeNull();
	});
});

import { describe, expect, it } from "bun:test";

import {
  applyNodePodRuntimeOverlay,
  DEFAULT_AGENT_RUNTIME_CONFIG,
  normalizeAgentRuntimeConfig,
  shouldAutoBootNodePod,
  shouldRouteExecutionToNodePod,
} from "../keating/agent-runtime";

describe("agent runtime config", () => {
  it("defaults to browser-only for missing or invalid config", () => {
    expect(normalizeAgentRuntimeConfig(null)).toEqual(DEFAULT_AGENT_RUNTIME_CONFIG);
    expect(normalizeAgentRuntimeConfig({ mode: "free" })).toEqual(DEFAULT_AGENT_RUNTIME_CONFIG);
  });

  it("preserves project file access in browser-only mode", () => {
    const config = normalizeAgentRuntimeConfig({
      mode: "browser-only",
      projectRoot: "/repo",
      projectFilesEndpoint: "/api/project-files",
    });

    expect(config.mode).toBe("browser-only");
    expect(config.executionEndpoint).toBeNull();
    expect(config.projectRoot).toBe("/repo");
    expect(config.projectFilesEndpoint).toBe("/api/project-files");
    expect(config.capabilities.hostProjectAccess).toBe(true);
  });

  it("preserves opt-in local exec access in browser-only mode", () => {
    const config = normalizeAgentRuntimeConfig({
      mode: "browser-only",
      projectRoot: "/repo",
      projectFilesEndpoint: "/api/project-files",
      localExecEndpoint: "/api/local-exec",
    });

    expect(config.mode).toBe("browser-only");
    expect(config.localExecEndpoint).toBe("/api/local-exec");
    expect(config.capabilities.localCommandExecution).toBe(true);
  });

  it("normalizes remote microVM config", () => {
    const config = normalizeAgentRuntimeConfig({
      mode: "remote",
      remote: {
        provider: "daytona",
        endpoint: "http://127.0.0.1:3929",
        region: "local",
      },
    });

    expect(config.mode).toBe("remote");
    expect(config.executionEndpoint).toBe("/api/agent-runtime/remote");
    expect(config.remote?.provider).toBe("daytona");
    expect(config.remote?.endpoint).toBe("http://127.0.0.1:3929");
    expect(config.capabilities.secureIsolation).toBe(true);
    expect(config.fallback.remoteAvailable).toBe(true);
  });

	it("does not advertise remote execution without an external endpoint", () => {
		const config = normalizeAgentRuntimeConfig({ mode: "remote" });

		expect(config.executionEndpoint).toBeNull();
		expect(config.capabilities.remoteSandbox).toBe(false);
		expect(config.fallback.remoteAvailable).toBe(false);
		expect(config.fallback.message).toContain("no external sandbox endpoint");
	});

	it("models direct host execution without claiming sandbox isolation", () => {
		const config = normalizeAgentRuntimeConfig({
			mode: "remote",
			executionEndpoint: "/api/agent-runtime/host",
			remote: { provider: "host", endpoint: "host://local" },
		});

		expect(config.label).toBe("Host execution agent");
		expect(config.capabilities.remoteSandbox).toBe(true);
		expect(config.capabilities.nativeBinaries).toBe(true);
		expect(config.capabilities.secureIsolation).toBe(false);
		expect(config.capabilities.serverBrokeredSecrets).toBe(false);
		expect(config.fallback.message).toContain("not a security sandbox");
	});

  it("normalizes cloud config with canonical default endpoint", () => {
    const config = normalizeAgentRuntimeConfig({ mode: "cloud" });

    expect(config.mode).toBe("cloud");
    expect(config.executionEndpoint).toBe("/api/agent-runtime/remote");
    expect(config.cloudEndpoint).toBe("https://keating.help");
    expect(config.capabilities.serverBrokeredSecrets).toBe(true);
  });

  it("keeps an explicit remote sandbox authoritative when NodePod is active", () => {
    const remote = normalizeAgentRuntimeConfig({
      mode: "remote",
      remote: { provider: "daytona", endpoint: "https://sandbox.example" },
    });

    expect(applyNodePodRuntimeOverlay(remote, true)).toBe(remote);
    expect(shouldAutoBootNodePod(remote)).toBe(false);
    expect(shouldRouteExecutionToNodePod(remote)).toBe(false);
  });

  it("uses NodePod as the automatic sandbox only in browser-only mode", () => {
    const nodepod = applyNodePodRuntimeOverlay(DEFAULT_AGENT_RUNTIME_CONFIG, true);

    expect(nodepod.mode).toBe("browser-nodepod");
    expect(nodepod.executionEndpoint).toBe("nodepod://local");
    expect(shouldAutoBootNodePod(DEFAULT_AGENT_RUNTIME_CONFIG)).toBe(true);
    expect(shouldRouteExecutionToNodePod(nodepod)).toBe(true);
  });
});

