export type KeatingAgentRuntimeMode = "browser-only" | "browser-nodepod" | "remote" | "cloud";

// Overlay NodePod browser sandbox when locally active
import { isNodePodActive, NODEPOD_LOCAL_ENDPOINT } from "./nodepod-runtime";

export interface KeatingRemoteAgentRuntimeConfig {
  provider: string;
  endpoint: string | null;
  region: string | null;
  snapshot: string | null;
  cpu: string | null;
  memory: string | null;
  disk: string | null;
}

export interface KeatingAgentRuntimeCapabilities {
  browserLocal: boolean;
  remoteSandbox: boolean;
  secureIsolation: boolean;
  nativeBinaries: boolean;
  serverBrokeredSecrets: boolean;
  durableCompute: boolean;
  hostProjectAccess: boolean;
  /** Opt-in localhost host command execution + file writes (keating web --allow-local-exec). */
  localCommandExecution: boolean;
}

export interface KeatingAgentRuntimeConfig {
  mode: KeatingAgentRuntimeMode;
  label: string;
  executionEndpoint: string | null;
  cloudEndpoint: string | null;
  projectRoot: string | null;
  projectFilesEndpoint: string | null;
  /** Base endpoint for local exec/write routes, or null when disabled. */
  localExecEndpoint: string | null;
  remote: KeatingRemoteAgentRuntimeConfig | null;
  capabilities: KeatingAgentRuntimeCapabilities;
  fallback: {
    localFirst: boolean;
    remoteAvailable: boolean;
    message: string;
  };
}

const DEFAULT_CLOUD_ENDPOINT = "https://keating.help";

export const DEFAULT_AGENT_RUNTIME_CONFIG: KeatingAgentRuntimeConfig = {
  mode: "browser-only",
  label: "Browser-only agent",
  executionEndpoint: null,
  cloudEndpoint: null,
  projectRoot: null,
  projectFilesEndpoint: null,
  localExecEndpoint: null,
  remote: null,
  capabilities: {
    browserLocal: true,
    remoteSandbox: false,
    secureIsolation: false,
    nativeBinaries: false,
    serverBrokeredSecrets: false,
    durableCompute: false,
    hostProjectAccess: false,
    localCommandExecution: false,
  },
  fallback: {
    localFirst: true,
    remoteAvailable: false,
    message: "Run supported agent work in the browser. Surface a fallback error for secure isolation, native binaries, brokered secrets, durable compute, or public inbound networking.",
  },
};

let runtimeConfigPromise: Promise<KeatingAgentRuntimeConfig> | null = null;

export function shouldAutoBootNodePod(config: KeatingAgentRuntimeConfig): boolean {
  return config.mode === "browser-only";
}

export function shouldRouteExecutionToNodePod(config: KeatingAgentRuntimeConfig | null | undefined): boolean {
  return config?.mode === "browser-nodepod";
}

export function nodePodControlAction(
  config: KeatingAgentRuntimeConfig | null | undefined,
  nodePodActive: boolean,
): "stop" | "boot" | null {
  if (nodePodActive) return "stop";
  return config?.mode === "browser-only" ? "boot" : null;
}

export function applyNodePodRuntimeOverlay(
  config: KeatingAgentRuntimeConfig,
  nodePodActive: boolean,
): KeatingAgentRuntimeConfig {
  // Explicit remote and cloud serving modes are authoritative. A stale or
  // manually booted local pod must never capture work intended for an external
  // sandbox.
  if (!nodePodActive || config.mode !== "browser-only") return config;

  return {
    ...config,
    mode: "browser-nodepod",
    label: "Browser + NodePod agent",
    executionEndpoint: NODEPOD_LOCAL_ENDPOINT,
    capabilities: {
      ...config.capabilities,
      remoteSandbox: true,
      secureIsolation: false,
      nativeBinaries: false,
    },
    fallback: {
      localFirst: true,
      remoteAvailable: true,
      message: "NodePod browser sandbox is active. Run filesystem, shell, and snapshot work locally. Secure isolation, native binaries, and server-brokered secrets still require a remote backend.",
    },
  };
}

export function normalizeAgentRuntimeConfig(value: unknown): KeatingAgentRuntimeConfig {
  if (!value || typeof value !== "object") return DEFAULT_AGENT_RUNTIME_CONFIG;
  const raw = value as Partial<KeatingAgentRuntimeConfig>;
  const mode = raw.mode === "remote" || raw.mode === "cloud" || raw.mode === "browser-only"
    ? raw.mode
    : "browser-only";

  if (mode === "browser-only") {
    const projectFilesEndpoint = raw.projectFilesEndpoint ?? null;
    const localExecEndpoint = raw.localExecEndpoint ?? null;
    return {
      ...DEFAULT_AGENT_RUNTIME_CONFIG,
      projectRoot: raw.projectRoot ?? null,
      projectFilesEndpoint,
      localExecEndpoint,
      capabilities: {
        ...DEFAULT_AGENT_RUNTIME_CONFIG.capabilities,
        hostProjectAccess: !!projectFilesEndpoint,
        localCommandExecution: !!localExecEndpoint,
      },
    };
  }

  const remote = raw.remote && typeof raw.remote === "object"
    ? {
        provider: String(raw.remote.provider || "microsandbox"),
        endpoint: raw.remote.endpoint || null,
        region: raw.remote.region || null,
        snapshot: raw.remote.snapshot || null,
        cpu: raw.remote.cpu || null,
        memory: raw.remote.memory || null,
        disk: raw.remote.disk || null,
      }
    : null;

  if (mode === "remote") {
	const executionEndpoint = raw.executionEndpoint ?? (remote?.endpoint ? "/api/agent-runtime/remote" : null);
	const remoteAvailable = !!executionEndpoint && !!remote?.endpoint;
	const hostProvider = remote?.provider === "host";
    return {
      mode,
	  label: remoteAvailable
		? (hostProvider ? "Host execution agent" : "Remote microVM agent")
		: (hostProvider ? "Host execution unavailable" : "Remote microVM unavailable"),
	  executionEndpoint,
      cloudEndpoint: null,
      projectRoot: raw.projectRoot ?? null,
      projectFilesEndpoint: raw.projectFilesEndpoint ?? null,
      localExecEndpoint: raw.localExecEndpoint ?? null,
      remote: remote ?? {
        provider: "microsandbox",
        endpoint: null,
        region: null,
        snapshot: null,
        cpu: null,
        memory: null,
        disk: null,
      },
      capabilities: {
        browserLocal: true,
		remoteSandbox: remoteAvailable,
		secureIsolation: remoteAvailable && !hostProvider,
		nativeBinaries: remoteAvailable,
		serverBrokeredSecrets: remoteAvailable && !hostProvider,
		durableCompute: remoteAvailable && !hostProvider,
        hostProjectAccess: !!raw.projectFilesEndpoint,
        localCommandExecution: !!raw.localExecEndpoint,
      },
      fallback: {
        localFirst: true,
		remoteAvailable,
		message: remoteAvailable
			? (hostProvider
				? "Host execution is enabled. Commands run directly on the serving machine inside the configured project root; this is not a security sandbox."
				: "Run browser-compatible work locally first. Route secure isolation, native binaries, brokered secrets, durable compute, and public networking to the configured remote sandbox.")
			: "Remote mode was requested, but no external sandbox endpoint is configured.",
      },
    };
  }

  return {
    mode,
    label: "Keating Cloud agent",
    executionEndpoint: "/api/agent-runtime/remote",
    cloudEndpoint: raw.cloudEndpoint || DEFAULT_CLOUD_ENDPOINT,
    projectRoot: raw.projectRoot ?? null,
    projectFilesEndpoint: raw.projectFilesEndpoint ?? null,
    localExecEndpoint: raw.localExecEndpoint ?? null,
    remote: null,
    capabilities: {
      browserLocal: true,
      remoteSandbox: true,
      secureIsolation: true,
      nativeBinaries: true,
      serverBrokeredSecrets: true,
      durableCompute: true,
      hostProjectAccess: !!raw.projectFilesEndpoint,
      localCommandExecution: !!raw.localExecEndpoint,
    },
    fallback: {
      localFirst: true,
      remoteAvailable: true,
      message: "Run browser-compatible work locally first. Route remote-only work through the canonical Keating Cloud backend.",
    },
  };
}

export async function loadAgentRuntimeConfig(force = false): Promise<KeatingAgentRuntimeConfig> {
  if (runtimeConfigPromise && !force) return runtimeConfigPromise;
  runtimeConfigPromise = fetch("/api/agent-runtime/config", { headers: { accept: "application/json" } })
    .then((response) => response.ok ? response.json() : DEFAULT_AGENT_RUNTIME_CONFIG)
    .then(normalizeAgentRuntimeConfig)
    .then((config) => applyNodePodRuntimeOverlay(config, isNodePodActive()))
    .catch(() => DEFAULT_AGENT_RUNTIME_CONFIG);
  return runtimeConfigPromise;
}

import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { access, readdir, stat } from "node:fs/promises";
import { spawn } from "node:child_process";
import { color } from "../core/theme.js";

export type WebAgentRuntimeMode = "browser-only" | "remote" | "cloud";

export interface ServeWebOptions {
  agentRuntimeMode?: WebAgentRuntimeMode;
  /**
   * Absolute path to the host directory the web server should treat as the
   * current project root. When set (or when defaulted to the CLI's cwd),
   * the Nitro server exposes /api/project-files/** for the browser agent to
   * read project sources on demand. Defaults to undefined when unset.
   */
  projectRoot?: string;
  /**
   * When true, the project-files route skips .gitignore/.ignore filtering.
   * Hard-blocked dirs (.git, node_modules) are still refused for safety.
   */
  noIgnore?: boolean;
  /**
   * Opt-in local command/file mutation capability for trusted localhost use.
   * When enabled, the web server exposes /api/local-exec/** so browser tools
   * can run commands and write files scoped to the configured project root.
   */
  allowLocalExec?: boolean;
  remoteProvider?: string;
  remoteEndpoint?: string;
  remoteRegion?: string;
  remoteSnapshot?: string;
  remoteCpu?: string;
  remoteMemory?: string;
  remoteDisk?: string;
  cloudEndpoint?: string;
}

const WEB_SOURCE_PATHS = [
  "src",
  "public",
  "index.html",
  "package.json",
  "vite.config.ts",
  "nitro.config.ts",
];

async function newestMtimeMs(path: string): Promise<number> {
  try {
    const entry = await stat(path);
    if (!entry.isDirectory()) return entry.mtimeMs;

    let newest = entry.mtimeMs;
    const children = await readdir(path, { withFileTypes: true });
    for (const child of children) {
      newest = Math.max(newest, await newestMtimeMs(join(path, child.name)));
    }
    return newest;
  } catch {
    return 0;
  }
}

async function warnIfWebBuildIsStale(pkgRoot: string, nitroServerPath: string): Promise<void> {
  const buildMtimeMs = (await stat(nitroServerPath)).mtimeMs;
  const webRoot = join(pkgRoot, "web");

  let newestSourceMtimeMs = 0;
  for (const relativePath of WEB_SOURCE_PATHS) {
    newestSourceMtimeMs = Math.max(newestSourceMtimeMs, await newestMtimeMs(join(webRoot, relativePath)));
  }

  if (newestSourceMtimeMs <= buildMtimeMs) return;

  console.warn(`${color.warn}Warning: web sources are newer than web/.output.${color.reset}`);
  console.warn("`keating web` serves the last production build, not the live Vite source tree.");
  console.warn("Use `just web` for hot reload, or rebuild with `bun run --cwd web build` before launching.");
}

async function resolvePackageRoot(currentDir: string): Promise<string> {
  const candidates = [
    join(currentDir, "..", "..", ".."), // dist/src/cli/web.js -> project root
    join(currentDir, "..", ".."), // src/cli/web.ts -> project root
  ];

  for (const candidate of candidates) {
    const nitroServerPath = join(candidate, "web", ".output", "server", "index.mjs");
    try {
      await access(nitroServerPath);
      return candidate;
    } catch {
      // Keep looking; source and compiled entrypoints sit at different depths.
    }
  }

  return candidates[0];
}

/**
 * Starts the Keating Web UI server using Nitro.
 * Port-incrementing logic is now handled by Nitro's runtime 
 * or can be passed via the PORT environment variable.
 */
export async function serveWeb(port = 3000, options: ServeWebOptions = {}): Promise<void> {
  const currentDir = dirname(fileURLToPath(import.meta.url));
  const pkgRoot = await resolvePackageRoot(currentDir);
  const nitroServerPath = join(pkgRoot, "web", ".output", "server", "index.mjs");

  try {
    await access(nitroServerPath);
  } catch (error) {
    console.error(`${color.err}Error: Could not find Nitro server at ${nitroServerPath}${color.reset}`);
    console.error("Please run the build command first:");
    console.error("  bun run --cwd web build");
    process.exit(1);
  }

  await warnIfWebBuildIsStale(pkgRoot, nitroServerPath);

  const mode = options.agentRuntimeMode ?? "browser-only";
  const projectRoot = options.projectRoot ?? "";
  const noIgnore = options.noIgnore ?? false;
  const allowLocalExec = options.allowLocalExec ?? false;
  process.stdout.write(`${color.ok}${color.bold} Keating Web Server ${color.reset}  ${color.parchment}port ${port}${color.reset}  ${color.sepia}agent=${mode}${color.reset}${projectRoot ? `  ${color.sepia}root=${projectRoot}${color.reset}` : ""}${noIgnore ? `  ${color.sepia}no-ignore${color.reset}` : ""}${allowLocalExec ? `  ${color.warn}local-exec${color.reset}` : ""}\n`);
  if (allowLocalExec) {
    console.warn(`${color.warn}Warning: local exec is enabled. Browser tools can run commands and write files inside ${projectRoot || "the project root"}.${color.reset}`);
  }

  const env = {
    ...process.env,
    PORT: port.toString(),
    NITRO_PORT: port.toString(),
    KEATING_WEB_AGENT_MODE: mode,
    KEATING_WEB_PROJECT_ROOT: projectRoot,
    KEATING_WEB_PROJECT_NO_IGNORE: noIgnore ? "1" : "",
    KEATING_WEB_LOCAL_EXEC: allowLocalExec ? "1" : "",
    KEATING_WEB_REMOTE_PROVIDER: options.remoteProvider ?? process.env.KEATING_WEB_REMOTE_PROVIDER ?? "",
    KEATING_WEB_REMOTE_ENDPOINT: options.remoteEndpoint ?? process.env.KEATING_WEB_REMOTE_ENDPOINT ?? "",
    KEATING_WEB_REMOTE_REGION: options.remoteRegion ?? process.env.KEATING_WEB_REMOTE_REGION ?? "",
    KEATING_WEB_REMOTE_SNAPSHOT: options.remoteSnapshot ?? process.env.KEATING_WEB_REMOTE_SNAPSHOT ?? "",
    KEATING_WEB_REMOTE_CPU: options.remoteCpu ?? process.env.KEATING_WEB_REMOTE_CPU ?? "",
    KEATING_WEB_REMOTE_MEMORY: options.remoteMemory ?? process.env.KEATING_WEB_REMOTE_MEMORY ?? "",
    KEATING_WEB_REMOTE_DISK: options.remoteDisk ?? process.env.KEATING_WEB_REMOTE_DISK ?? "",
    KEATING_WEB_CLOUD_ENDPOINT: options.cloudEndpoint ?? process.env.KEATING_WEB_CLOUD_ENDPOINT ?? "https://keating.help"
  };

  // Run the Nitro server in a child process
  const child = spawn(process.execPath, [nitroServerPath], {
    env,
    stdio: "inherit",
  });

  child.on("error", (err) => {
    console.error(`${color.err}Failed to start Nitro server:${color.reset}`, err);
  });

  // Handle termination signals
  const cleanup = () => {
    child.kill();
    process.exit();
  };

  process.on("SIGINT", cleanup);
  process.on("SIGTERM", cleanup);
}

