import { createError } from "h3";
import { readFile, readdir, stat, writeFile } from "node:fs/promises";
import { relative } from "node:path";
import {
    resolveCwdWithinRoot,
    resolveExistingPathWithinRoot,
    resolveWritePathWithinRoot,
    runCommand,
} from "./local-exec";

function payloadRecord(payload: unknown): Record<string, unknown> {
    return payload && typeof payload === "object" && !Array.isArray(payload)
        ? payload as Record<string, unknown>
        : {};
}

function workspaceRelative(value: unknown): string {
    const path = typeof value === "string" ? value.trim() : "";
    if (path === "/workspace") return "";
    if (path.startsWith("/workspace/")) return path.slice("/workspace/".length);
    return path.replace(/^\/+/, "");
}

function requiredString(payload: Record<string, unknown>, key: string): string {
    const value = typeof payload[key] === "string" ? payload[key].trim() : "";
    if (!value) throw createError({ statusCode: 400, statusMessage: `${key} is required` });
    return value;
}

export async function executeHostAgentOperation(
    root: string,
    operation: string,
    rawPayload: unknown,
): Promise<unknown> {
    const payload = payloadRecord(rawPayload);

    switch (operation) {
        case "runtime.ping":
            return { ok: true, provider: "host", root, timestamp: Date.now() };

        case "shell.exec": {
            const command = requiredString(payload, "command");
            const args = Array.isArray(payload.args) ? payload.args.map(String) : [];
            const cwd = await resolveCwdWithinRoot(root, workspaceRelative(payload.cwd));
            const timeoutMs = typeof payload.timeoutMs === "number" ? payload.timeoutMs : undefined;
            const env = payload.env && typeof payload.env === "object" && !Array.isArray(payload.env)
                ? Object.fromEntries(Object.entries(payload.env as Record<string, unknown>).map(([key, value]) => [key, String(value)]))
                : undefined;
            return runCommand({ command, args, cwd, timeoutMs, env });
        }

        case "fs.list": {
            const target = await resolveExistingPathWithinRoot(root, workspaceRelative(payload.path));
            const entries = await readdir(target, { withFileTypes: true });
            return Promise.all(entries.map(async (entry) => {
                const path = await resolveExistingPathWithinRoot(root, relative(root, `${target}/${entry.name}`));
                const info = await stat(path);
                return {
                    name: entry.name,
                    path: relative(root, path).split(/[\\/]/g).join("/"),
                    isDir: entry.isDirectory(),
                    size: info.size,
                    modTime: info.mtime.toISOString(),
                };
            }));
        }

        case "fs.read": {
            const target = await resolveExistingPathWithinRoot(root, workspaceRelative(payload.path));
            const encoding = payload.encoding === "base64" ? "base64" : "utf8";
            const content = await readFile(target, encoding);
            return { path: relative(root, target).split(/[\\/]/g).join("/"), content, encoding };
        }

        case "fs.write": {
            const target = await resolveWritePathWithinRoot(root, workspaceRelative(payload.path));
            const encoding = payload.encoding === "base64" ? "base64" : "utf8";
            const content = typeof payload.content === "string" ? payload.content : "";
            const data = encoding === "base64" ? Buffer.from(content, "base64") : content;
            await writeFile(target, data);
            return { ok: true, path: relative(root, target).split(/[\\/]/g).join("/"), bytes: Buffer.byteLength(data), encoding };
        }

        case "fs.edit": {
            const target = await resolveExistingPathWithinRoot(root, workspaceRelative(payload.path));
            const search = requiredString(payload, "search");
            const replace = typeof payload.replace === "string" ? payload.replace : "";
            const content = await readFile(target, "utf8");
            const occurrences = content.split(search).length - 1;
            if (occurrences !== 1) {
                throw createError({
                    statusCode: 409,
                    statusMessage: occurrences === 0
                        ? "search block was not found"
                        : `search block appears ${occurrences} times`,
                });
            }
            await writeFile(target, content.replace(search, replace), "utf8");
            return { ok: true, path: relative(root, target).split(/[\\/]/g).join("/") };
        }

        case "source.diff": {
            const path = workspaceRelative(payload.path);
            const args = ["diff", "--"];
            if (path) args.push(path);
            return runCommand({ command: "git", args, cwd: root });
        }

        default:
            throw createError({ statusCode: 400, statusMessage: `Unsupported host operation: ${operation}` });
    }
}
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { access, readdir, stat } from "node:fs/promises";
import { spawn } from "node:child_process";
import { color } from "../core/theme.js";

export type WebAgentRuntimeMode = "browser-only" | "remote" | "cloud";

export interface ServeWebOptions {
  agentRuntimeMode?: WebAgentRuntimeMode;
  /**
   * Absolute path to the host directory the web server should treat as the
   * current project root. When set (or when defaulted to the CLI's cwd),
   * the Nitro server exposes /api/project-files/** for the browser agent to
   * read project sources on demand. Defaults to undefined when unset.
   */
  projectRoot?: string;
  /**
   * When true, the project-files route skips .gitignore/.ignore filtering.
   * Hard-blocked dirs (.git, node_modules) are still refused for safety.
   */
  noIgnore?: boolean;
  /**
   * Opt-in local command/file mutation capability for trusted localhost use.
   * When enabled, the web server exposes /api/local-exec/** so browser tools
   * can run commands and write files scoped to the configured project root.
   */
  allowLocalExec?: boolean;
  remoteProvider?: string;
  remoteEndpoint?: string;
  remoteRegion?: string;
  remoteSnapshot?: string;
  remoteCpu?: string;
  remoteMemory?: string;
  remoteDisk?: string;
  cloudEndpoint?: string;
}

const WEB_SOURCE_PATHS = [
  "src",
  "public",
  "index.html",
  "package.json",
  "vite.config.ts",
  "nitro.config.ts",
];

async function newestMtimeMs(path: string): Promise<number> {
  try {
    const entry = await stat(path);
    if (!entry.isDirectory()) return entry.mtimeMs;

    let newest = entry.mtimeMs;
    const children = await readdir(path, { withFileTypes: true });
    for (const child of children) {
      newest = Math.max(newest, await newestMtimeMs(join(path, child.name)));
    }
    return newest;
  } catch {
    return 0;
  }
}

async function warnIfWebBuildIsStale(pkgRoot: string, nitroServerPath: string): Promise<void> {
  const buildMtimeMs = (await stat(nitroServerPath)).mtimeMs;
  const webRoot = join(pkgRoot, "web");

  let newestSourceMtimeMs = 0;
  for (const relativePath of WEB_SOURCE_PATHS) {
    newestSourceMtimeMs = Math.max(newestSourceMtimeMs, await newestMtimeMs(join(webRoot, relativePath)));
  }

  if (newestSourceMtimeMs <= buildMtimeMs) return;

  console.warn(`${color.warn}Warning: web sources are newer than web/.output.${color.reset}`);
  console.warn("`keating web` serves the last production build, not the live Vite source tree.");
  console.warn("Use `just web` for hot reload, or rebuild with `bun run --cwd web build` before launching.");
}

async function resolvePackageRoot(currentDir: string): Promise<string> {
  const candidates = [
    join(currentDir, "..", "..", ".."), // dist/src/cli/web.js -> project root
    join(currentDir, "..", ".."), // src/cli/web.ts -> project root
  ];

  for (const candidate of candidates) {
    const nitroServerPath = join(candidate, "web", ".output", "server", "index.mjs");
    try {
      await access(nitroServerPath);
      return candidate;
    } catch {
      // Keep looking; source and compiled entrypoints sit at different depths.
    }
  }

  return candidates[0];
}

