export function normalizeEmail(email: string): string {
	return email.trim().toLowerCase();
}

export function dioOpenAiBaseUrl(origin = currentOrigin()): string {
	return `${origin.replace(/\/+$/, "")}${DIO_BASE_PATH}`;
